INSERT INTO "movies" ("id","title","description","cover_image","detail_images","genres","rating","duration_min","created_at","updated_at","is_active","release_date") VALUES(1,'THÁM HIỂM VÙNG ĐẤT MA','Phim mang yếu tố kích thích, rùng rợn','https://res.cloudinary.com/dzp3rbeix/image/upload/v1768718935/ctbooking/movies/kqrscd7ofggobb3pqjxt.webp','null',X'',8,7,'2025-12-15 02:15:31','2026-03-16T10:41:21.906Z',1,'2025-12-13T06:02:00.000Z');
INSERT INTO "movies" ("id","title","description","cover_image","detail_images","genres","rating","duration_min","created_at","updated_at","is_active","release_date") VALUES(2,'Thế giới khủng long',replace('Con người đã dùng công nghệ mới để hồi sinh gen của khủng long, và trên một hòn đảo đã ấp nở nhiều con khủng long, hình thành nên Đảo Khủng Long Jurassic.\nVào một ngày, chúng ta theo bước chân của Archi, bắt đầu một hành trình kỳ diệu khám phá đảo khủng long.\nTại đây, chúng ta có thể tham quan và tiếp xúc gần với những loài khủng long sống từ thời cổ đại: Pteranodon bay lượn trên bầu trời, khủng long ăn cỏ chạy tìm thức ăn—mọi thứ đều thật hòa hợp.\nBất ngờ, cơn tấn công của Pteranodon và cuộc săn mồi của yrannosaurus làm gián đoạn chuyến tham quan. Để tránh bị truy đuổi, chúng ta băng qua những hẻm núi hẹp, bay qua thác nước dữ dội, và khi thoát khỏi đại hẻm, chứng kiến cảnh tượng di cư hùng vĩ của đàn khủng long 。','\n',char(10)),'https://res.cloudinary.com/dzp3rbeix/image/upload/v1768718834/ctbooking/movies/yaioivwyib95wwr67bry.webp','null','["Phiêu Lưu"]',9.5,5.5,'2025-12-15 02:15:31','2026-04-12T14:22:13.047Z',1,'2025-12-26T06:03:00.000Z');
INSERT INTO "movies" ("id","title","description","cover_image","detail_images","genres","rating","duration_min","created_at","updated_at","is_active","release_date") VALUES(3,'Thám hiểm biển sâu',replace('Lần này, chúng ta sẽ cùng Chi Cốc khảo sát những thông tin đáng ngờ phát ra từ đáy đại dương, mở ra một cuộc khám phá bí ẩn dưới biển sâu.\nTàu ngầm xuất phát từ căn cứ ven biển, bay vòng quanh các đảo, rồi rơi thẳng xuống vùng biển nông. Khi lái tàu ngầm liên tục thám hiểm, chúng ta đi qua rạn san hô hình thành từ xác cá voi. Bị cá mập tấn công, để tránh nguy hiểm, tàu ngầm đi sâu vào vùng biển sâu. Bất ngờ, một con cá voi khổng lồ xuất hiện, dẫn chúng ta vào vùng biển bí ẩn.\nDo bị tấn công, động cơ bị hỏng, và trong vùng biển bí ẩn, chúng ta chứng kiến một trận chiến giữa quái vật biển khổng lồ và cá mập lớn. Nhân lúc hai sinh vật khổng lồ quấn nhau, Aki kịp sửa xong động cơ, và chúng ta nhanh chóng rút lui, cuối cùng trở về an toàn căn cứ biển sâu','\n',char(10)),'https://res.cloudinary.com/dzp3rbeix/image/upload/v1767688017/ctbooking/movies/ti4l5zt5pxolmbvlxx38.webp','null',X'',9.5,5.34,'2025-12-15 02:15:31','2026-03-16T10:42:06.080Z',1,'2025-12-24T14:30:00.000Z');
INSERT INTO "movies" ("id","title","description","cover_image","detail_images","genres","rating","duration_min","created_at","updated_at","is_active","release_date") VALUES(4,'Hành Trình Giữa Các Vì Sao',replace('Thế giới tương lai\nSự phát triển của AI đã đạt đến mức chưa từng có. Trong những lần lặp\nlại và tiến hóa liên tiếp, các siêu AI đã hình thành ý thức tự thân, khiến\nxung đột giữa con người và AI ngày càng gia tăng, từ Trái Đất lan rộng\nra toàn bộ vũ trụ.\nĐể ngăn chặn tình trạng AI ngoài tầm kiểm soát, con người đã xây\ndựng căn cứ không gian trên sao Hỏa, bí mật nghiên cứu vũ khí tối\nthượng có thể vô hiệu hóa AI, đồng thời cử lực lượng tinh nhuệ thực\nhiện nhiệm vụ khó khăn này. Dưới sự dẫn dắt của phi hành đoàn Bạch\nTrạch, các chiến binh tinh nhuệ đã thoát khỏi sự truy đuổi của tàu địch,\nbí mật giao nhận trong không gian, trải qua muôn trùng hiểm nguy,\nxuyên qua lỗ sâu để đến bề mặt sao Hỏa, chuẩn bị hoàn thành nhiệm\nvụ cuối cùng.\nTuy nhiên, sau một cơn bão mặt trời, giữa vũ trụ bao la chỉ còn lại một\nkhoảng lặng màu đen. Liệu nhiệm vụ có thể hoàn thành hay không?!','\n',char(10)),'https://res.cloudinary.com/dzp3rbeix/image/upload/v1767688064/ctbooking/movies/grodyl2fsi1uydyplzsx.webp','null',X'',9.5,4.53,'2025-12-15 02:15:31','2026-01-31T08:45:28.686Z',1,'2025-12-24T14:30:00.000Z');
INSERT INTO "movies" ("id","title","description","cover_image","detail_images","genres","rating","duration_min","created_at","updated_at","is_active","release_date") VALUES(5,'Vùng đất đỏ',replace('Siêu tàu vũ trụ Chāoyuán đang thực hiện chuyến du hành giữa các vì sao\nbất ngờ rơi vào hố đen, và vượt không gian tới hành tinh Kepler-22b cách\n600 năm ánh sáng. Là một trong những hành tinh ngoài Trái Đất có khả\nnăng sinh sống cao nhất, ở đây xuất hiện những dao động năng lượng\nmạnh mẽ trong lõi hành tinh. Hãy cùng hướng dẫn viên Bạch Trạch và\nChi Cốc thâm nhập vào lòng đất, tránh các đợt tấn công và hoàn thành\nnhiệm vụ thăm dò!\nTrò chơi sinh tử giữa người và máy | Chiến trường tối thượng giữa các vì\nsao | Đội tinh nhuệ tập hợp | Căn cứ bí mật trên Sao Hỏa | Nghiên cứu vũ\nkhí tối thượng | Giao nhận bí mật trong không gian | Trải nghiệm du hành\nqua lỗ sâu | Khủng hoảng bão mặt trời | Truy đuổi trong không gian | Bí ẩn\nvũ trụ tĩnh lặng | Nhiệm vụ đầy kịch tính | Nhảy không gian liên sao | Nguy\nhiểm trong vũ trụ chưa biết','\n',char(10)),'https://res.cloudinary.com/dzp3rbeix/image/upload/v1768718606/ctbooking/movies/rix3brtpigngjxoutnaq.webp','null',X'',9.5,5.41,'2025-12-15 02:15:31','2026-01-18T06:43:19.190Z',1,'2025-12-24T14:30:00.000Z');
INSERT INTO "movies" ("id","title","description","cover_image","detail_images","genres","rating","duration_min","created_at","updated_at","is_active","release_date") VALUES(6,'Tề Thiên Đại Thánh',replace('Câu chuyện được chuyển thể từ tác phẩm kinh điển Trung Quốc “Tây Du Ký”. Câu chuyện kể về Tôn Ngộ Không – Tề Thiên Đại Thánh, người được sinh ra từ linh thạch của trời đất, vốn đã định sẵn là phi thường. Ngài lên ngôi vua ở Hoa Quả Sơn, tập hợp vô số khỉ yêu tinh, xây dựng cho mình một vương quốc riêng.\n\nDựa vào trí tuệ và tài năng, Tôn Ngộ Không lẻn vào Long Cung Đông Hải, tinh khôn lấy được Như Ý Kim Cô Bổng – cây định hải thần trượng. Ngộ Không tự tin rằng mình có thể làm mọi việc, dám thách thức quyền uy, không ngừng theo đuổi tự do và sức mạnh. Ngài quậy phá Thiên Cung, dựa vào thất thập nhị biến và Cân Đẩu Vân, cùng các vị thần trên Thiên Đình tham gia những trận chiến khốc liệt.\n\nSự dũng cảm phi thường của Tôn Ngộ Không khiến các thần tiên phải nhìn nhận lại. Mặc dù cuối cùng bị Phật Như Lai trấn dưới Ngũ Hành Sơn, nhưng trải nghiệm huyền thoại cùng tinh thần không khuất phục của ngài vẫn luôn thu hút và truyền cảm hứng từ thế hệ này sang thế hệ khác.','\n',char(10)),'https://res.cloudinary.com/dzp3rbeix/image/upload/v1768718973/ctbooking/movies/rtjd1rbwvblnmls0ojjp.webp','null',X'',9.4,8.36,'2025-12-15 02:15:31','2026-01-18T06:49:32.711Z',0,'2025-12-24T02:30:00.000Z');
